#include <bits/stdc++.h>
using namespace std;

vector<int> parent, sz;

int find(int x) {
    while (parent[x] != x) {
        parent[x] = parent[parent[x]];
        x = parent[x];
    }
    return x;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    parent.resize(n);
    sz.assign(n, 1);
    iota(parent.begin(), parent.end(), 0);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a = find(a - 1);
        b = find(b - 1);
        if (a != b) {
            if (sz[a] < sz[b]) swap(a, b);
            parent[b] = a;
            sz[a] += sz[b];
        }
    }
    // All unordered pairs minus the pairs inside each component.
    long long answer = (long long)n * (n - 1) / 2;
