}

import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    static int[] parent, sz;

    static int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), m = nextInt();
        parent = new int[n];
        sz = new int[n];
        for (int i = 0; i < n; i++) {
            parent[i] = i;
            sz[i] = 1;
        }
        for (int i = 0; i < m; i++) {
            int a = find(nextInt() - 1), b = find(nextInt() - 1);
            if (a != b) {
                if (sz[a] < sz[b]) {
                    int t = a;
                    a = b;
                    b = t;
                }
                parent[b] = a;
                sz[a] += sz[b];
            }
        }
        // All unordered pairs minus the pairs inside each component.
        long answer = (long) n * (n - 1) / 2;
        for (int i = 0; i < n; i++)
            if (parent[i] == i) answer -= (long) sz[i] * (sz[i] - 1) / 2;
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := nextInt(), nextInt()
	parent := make([]int, n)
	sz := make([]int, n)
	for i := range parent {
		parent[i], sz[i] = i, 1
	}
	find := func(x int) int {
		for parent[x] != x {
			parent[x] = parent[parent[x]]
			x = parent[x]
		}
		return x
	}
	for i := 0; i < m; i++ {
		a, b := find(nextInt()-1), find(nextInt()-1)
		if a != b {
			if sz[a] < sz[b] {
				a, b = b, a
			}
			parent[b] = a
			sz[a] += sz[b]
		}
	}
	// All unordered pairs minus the pairs inside each component.
	answer := n * (n - 1) / 2
	for i := 0; i < n; i++ {
		if parent[i] == i {
			answer -= sz[i] * (sz[i] - 1) / 2
		}
	}
	fmt.Println(answer)
}
